using System.Collections;
static partial class JoinedFactoryProbe
{
    static int MsiManualPublicAttempts,MsiManualPublicSuccess,MsiManualOpenCycles;
    static Array ManualNodes(params(double temperature,double duty)[] values)
    {
        var type=Host.GetType("YeManFanHost.FanNode",true)!;var nodes=Array.CreateInstance(type,values.Length);for(var i=0;i<values.Length;i++)nodes.SetValue(Activator.CreateInstance(type,All,null,[values[i].temperature,values[i].duty],null),i);return nodes;
    }
    static bool ApplyManual(object backend,Array? nodes=null,long? epoch=null)
    {
        MsiManualPublicAttempts++;var result=Invoke(backend,"ApplyCurve",nodes??ManualNodes((0,0),(30,30),(70,70),(100,100)),epoch);Check(result is true,"Actual public MSI ApplyCurve must publish accepted control only after all original writers verify");MsiManualPublicSuccess++;return true;
    }
    static object ManualSubmission(object backend){var value=Get(backend,"lastMsiFamilySubmission");Check(value is not null,"Manual operation must retain its actual structured submission");return value!;}
    static void ManualCase(string id,Action<object> body,string product="MS-1T41",string expected="ClawA1M",int firmware=0x167)
    {
        MsiCase(id,backend=>
        {
            MsiManualIoPorts.Reset();try
            {
                OpenPublic(backend);Invoke(backend,"OpenEvents");MsiManualOpenCycles++;MsiLifecycleIoPorts.Full=0x85;MsiLifecycleIoPorts.Software=0x11;MsiManualIoPorts.Rows.Clear();body(backend);
                MsiManualIoPorts.OnIo=null;MsiManualIoPorts.FailedRead=MsiManualIoPorts.FailedWrite="";MsiManualIoPorts.IgnoreWrite=false;ClosePublic(backend);
                Check(MsiManualIoPorts.ContractRejections==0,"Every actual manual WMI scope/path/index/length/minimum must match its independent fixed contract");
            }
            finally{MsiManualIoPorts.OnIo=null;MsiManualIoPorts.Enabled=false;}
        },product,expected,firmware);
    }
    static object ReplacementMsiDevice(object backend){object? value=null;Sta(backend,()=>value=Activator.CreateInstance(LifecycleDevice(backend).GetType()),"manual-replacement-constructor");return value!;}
    static readonly (string product,string name,int firmware)[] ManualModels=[("MS-1T41","ClawA1M",0x167),("MS-1T52","ClawA2VM",0x219),("MS-1T8K","ClawBZ2EM",0x308),("MS-1T91","ClawCG3EM",0x411)];
    static object[] ManualBlocks(object backend)=>((IEnumerable)Get(ManualSubmission(backend),"Blocks")!).Cast<object>().ToArray();
    static void NotCommitted(object backend){var result=ManualSubmission(backend);Check(Get(result,"Success")is false&&Get(result,"CommitAccepted")is false&&Get(backend,"activeMsiCurveNodes")is null&&MsiManualIoPorts.TimerArms==0,"Failed actual manual submission cannot publish control intent or arm replay");}
    static void RunMsiManualCases()
    {
        foreach(var row in ManualModels)
            ManualCase("msi-manual-original-public-linear:"+row.name,backend=>
            {
                var before=MsiManualIoPorts.Tables.Select(b=>b.ToArray()).ToArray();ApplyManual(backend);var submission=ManualSubmission(backend);Check(Get(submission,"Success")is true&&Get(submission,"CommitAccepted")is true&&Get(submission,"PhysicalRpmConfirmed")is false,"Actual Host records current table/control commit without fabricating physical RPM");
                var writes=MsiManualIoPorts.Rows.Where(r=>r.Stage=="write").ToArray();Check(writes.Select(r=>r.Index).SequenceEqual(new[]{1,2,212,152}),"Actual public MSI writes both original tables before software and normal full-speed control");
                var expectedDuties=new[]{new byte[]{0,75,90,105,120,132},new byte[]{0,60,75,90,105,120}};
                for(var i=0;i<2;i++){Check(writes[i].Length==32&&writes[i].Data.Skip(2).Take(6).SequenceEqual(expectedDuties[i]),"Original public MSI interpolation uses each actual firmware temperature axis");Check(writes[i].Data[1]==before[i][0]&&writes[i].Data[8]==before[i][7]&&writes[i].Data.Skip(9).SequenceEqual(before[i].Skip(8)),"Original HC writer preserves both boundaries and every untouched byte of the31-byte payload");}
                Check(MsiManualIoPorts.Rows.Take(2).All(r=>r.Method=="Get_Temperature")&&MsiManualIoPorts.TimerArms==1,"Both original temperature axes are read before any write, and only actual one-shot timer arming is isolated");
            },row.product,row.name,row.firmware);
        ManualCase("msi-manual-original-epoch-before-write",backend=>{MsiManualIoPorts.OnIo=row=>{if(row.Method=="Get_Temperature"){MsiManualIoPorts.OnIo=null;Set(backend,"suspendGateEpoch",1L);}};Reject(()=>ApplyManual(backend),"FAN_WRITE_SUPERSEDED");Check(MsiManualIoPorts.Rows.All(r=>r.Stage!="write")&&Get(ManualSubmission(backend),"CommitAccepted")is false,"Superseded epoch cannot issue either original table write");});
        ManualCase("msi-manual-original-device-replaced",backend=>{var original=LifecycleDevice(backend);var replacement=ReplacementMsiDevice(backend);MsiManualIoPorts.OnIo=row=>{if(row.Method=="Get_Temperature"){MsiManualIoPorts.OnIo=null;Set(backend,"device",replacement);}};try{Reject(()=>ApplyManual(backend),"FAN_WRITE_SUPERSEDED");Check(MsiManualIoPorts.Rows.All(r=>r.Stage!="write"),"Replaced original MSI device cannot continue the captured transport write");}finally{Set(backend,"device",original);DisposeDevice(replacement);}});
        ManualCase("msi-manual-original-assembly-replaced",backend=>{var original=Get(backend,"assembly");MsiManualIoPorts.OnIo=row=>{if(row.Method=="Get_Temperature"){MsiManualIoPorts.OnIo=null;Set(backend,"assembly",typeof(MsiManualIoPorts).Assembly);}};try{Reject(()=>ApplyManual(backend),"FAN_WRITE_SUPERSEDED");Check(MsiManualIoPorts.Rows.All(r=>r.Stage!="write"),"Replaced original assembly owner cannot continue captured MSI writes");}finally{Set(backend,"assembly",original);}});
        foreach(var row in ManualModels)
        {
            ManualCase("msi-manual-original-flat-fullspeed:"+row.name,backend=>{ApplyManual(backend,ManualNodes((0,100),(30,100),(70,100),(100,100)));var result=ManualSubmission(backend);Check(Get(result,"FullSpeedRequested")is true&&Get(result,"Success")is true&&(MsiLifecycleIoPorts.Full&0x80)!=0,"Explicit flat100 public intent must preserve actual full-speed override");Check(MsiManualIoPorts.Rows.Where(r=>r.Stage=="write"&&r.Method=="Set_Fan").All(r=>r.Data.Skip(2).Take(6).All(b=>b==150)),"Flat100 converts all six actual duties into the original150 raw scale");},row.product,row.name,row.firmware);
            ManualCase("msi-manual-original-fullspeed-to-curve:"+row.name,backend=>{ApplyManual(backend,ManualNodes((0,100),(30,100),(70,100),(100,100)));var first=ManualSubmission(backend);Check(Get(first,"FullSpeedRequested")is true&&(MsiLifecycleIoPorts.Full&0x80)!=0,"First public full-speed intent must be actual before normal replacement");ApplyManual(backend);var second=ManualSubmission(backend);Check(!ReferenceEquals(first,second)&&Get(second,"FullSpeedRequested")is false&&Get(second,"Success")is true&&MsiLifecycleIoPorts.Full==5&&MsiManualIoPorts.TimerArms==2,"A new actual curve clears only full-speed bit7 and replaces its receipt and one-shot intent");},row.product,row.name,row.firmware);
        }
        foreach(var length in new[]{0,7,8,30})ManualCase("msi-manual-original-short-table:"+length,backend=>{MsiManualIoPorts.TableReadLength=length;Reject(()=>ApplyManual(backend),"FAN_CURVE_WRITE_FAILED");NotCommitted(backend);Check(MsiManualIoPorts.Rows.All(r=>r.Stage!="write")&&ManualBlocks(backend).All(b=>Get(b,"WriteDisposition")?.ToString()=="not-written"),"A short original31-byte block cannot be zero-padded into a fabricated full write");});
        foreach(var block in new[]{1,2})ManualCase("msi-manual-original-table-read-failure:"+block,backend=>{MsiManualIoPorts.FailedRead="Get_Fan";MsiManualIoPorts.FailedBlock=block;Reject(()=>ApplyManual(backend),"FAN_CURVE_WRITE_FAILED");NotCommitted(backend);Check(MsiManualIoPorts.Rows.Where(r=>r.Stage=="write").All(r=>r.Method=="Set_Fan"&&r.Index!=block),"Failure of either original table keeps actual partial results without claiming software control");Check(Get(ManualBlocks(backend)[block-1],"WriteDisposition")?.ToString()=="not-written","Failed read proves that specific original table was not written");});
        foreach(var block in new[]{1,2})foreach(var outcome in new[]{"InParamsUnavailable","TransportFailed","Exception"})ManualCase("msi-manual-original-table-write-failure:"+block+":"+outcome,backend=>{MsiManualIoPorts.FailedWrite="Set_Fan";MsiManualIoPorts.FailedBlock=block;MsiManualIoPorts.Outcome=outcome;Reject(()=>ApplyManual(backend),"FAN_CURVE_WRITE_FAILED");NotCommitted(backend);Check(MsiManualIoPorts.Rows.Where(r=>r.Stage=="write").All(r=>r.Method=="Set_Fan"),"Failed original table confirmation cannot enable software or full-speed bits");Check(Get(ManualBlocks(backend)[block-1],"WriteDisposition")?.ToString()==(outcome=="InParamsUnavailable"?"not-written":"write-unknown"),"Original write uncertainty must distinguish no invocation from missing response");});
        ManualCase("msi-manual-original-table-readback-unavailable",backend=>{MsiManualIoPorts.FailedRead="Get_Fan";MsiManualIoPorts.FailedBlock=1;MsiManualIoPorts.FailureAfter=1;Reject(()=>ApplyManual(backend),"FAN_CURVE_WRITE_FAILED");NotCommitted(backend);Check(Get(ManualBlocks(backend)[0],"Status")?.ToString()=="unknown"&&Get(ManualBlocks(backend)[0],"WriteDisposition")?.ToString()=="written-unverified","Original transported table with missing readback remains written but unverified");});
        ManualCase("msi-manual-original-table-readback-mismatch",backend=>{MsiManualIoPorts.IgnoreWrite=true;Reject(()=>ApplyManual(backend),"FAN_CURVE_WRITE_FAILED");NotCommitted(backend);Check(ManualBlocks(backend).All(b=>Get(b,"Status")?.ToString()=="failed")&&MsiManualIoPorts.Rows.Where(r=>r.Stage=="write").All(r=>r.Method=="Set_Fan"),"WMI transport success cannot replace actual six-duty readback equality");});
        foreach(var (method,block,field)in new[]{("Get_AP",1,"SoftwareControlStatus"),("Get_Data",152,"FullSpeedStatus")})ManualCase("msi-manual-original-bit-read-failure:"+block,backend=>{MsiManualIoPorts.FailedRead=method;MsiManualIoPorts.FailedBlock=block;Reject(()=>ApplyManual(backend),"FAN_CURVE_WRITE_FAILED");NotCommitted(backend);Check(Get(ManualSubmission(backend),field)?.ToString()=="unknown","Actual required control bit failure remains unknown after successful tables");});
        foreach(var block in new[]{1,2,212,152})ManualCase("msi-manual-original-epoch-after-stage:"+block,backend=>{MsiManualIoPorts.OnIo=row=>{if(row.Stage=="write"&&row.Index==block){MsiManualIoPorts.OnIo=null;Set(backend,"suspendGateEpoch",1L);}};Reject(()=>ApplyManual(backend),"FAN_WRITE_SUPERSEDED");NotCommitted(backend);var prefix=new[]{1,2,212,152}.Take(Array.IndexOf(new[]{1,2,212,152},block)+1);Check(MsiManualIoPorts.Rows.Where(r=>r.Stage=="write").Select(r=>r.Index).SequenceEqual(prefix),"An in-flight original call may finish but a retired epoch cannot begin any later write stage or commit");});
        foreach(var owner in new[]{"device","assembly"})ManualCase("msi-manual-original-owner-after-table:"+owner,backend=>{var original=Get(backend,owner);var replacement=owner=="device"?ReplacementMsiDevice(backend):(object)typeof(MsiManualIoPorts).Assembly;MsiManualIoPorts.OnIo=row=>{if(row.Stage=="write"&&row.Index==1){MsiManualIoPorts.OnIo=null;Set(backend,owner,replacement);}};try{Reject(()=>ApplyManual(backend),"FAN_WRITE_SUPERSEDED");NotCommitted(backend);Check(MsiManualIoPorts.Rows.Count(r=>r.Stage=="write")==1,"Captured old owner cannot start table2 or either bit after table1 returns");}finally{Set(backend,owner,original);if(owner=="device")DisposeDevice(replacement);}});
        foreach(var kind in new[]{"short","unordered","unavailable"})ManualCase("msi-manual-original-axis-fallback:"+kind,backend=>{if(kind=="short")MsiManualIoPorts.Axes=[new byte[]{0},new byte[]{0}];else if(kind=="unordered")MsiManualIoPorts.Axes=[new byte[]{0,0,0,50,40,70,80,88},new byte[]{0,0,0,40,40,60,70,80}];else{MsiManualIoPorts.FailedRead="Get_Temperature";MsiManualIoPorts.FailedBlock=1;}ApplyManual(backend);var blocks=ManualBlocks(backend);Check(Get(blocks[0],"AxisSource")?.ToString()=="hc-legacy-sample-compatibility-axis-unknown"&&Get(ManualSubmission(backend),"Success")is true,"Unusable original temperature axis keeps explicit compatibility fallback without a fabricated live axis");Check(((int[])Get(blocks[0],"RequestedRawDuties")!).SequenceEqual(new[]{0,30,75,90,120,135}),"Compatibility fallback preserves the independently known original sample mapping");});
        ManualCase("msi-manual-original-current-receipt-after-failure",backend=>{ApplyManual(backend);var previous=ManualSubmission(backend);MsiManualIoPorts.IgnoreWrite=true;Reject(()=>ApplyManual(backend,ManualNodes((0,50),(30,50),(70,70),(100,100))),"FAN_CURVE_WRITE_FAILED");var current=ManualSubmission(backend);Check(!ReferenceEquals(previous,current)&&Get(previous,"Success")is true&&Get(current,"Success")is false&&Get(current,"CommitAccepted")is false,"A later real manual failure cannot retain an earlier successful operation receipt");});
        ManualCase("msi-manual-original-invalid-public-curves",backend=>{foreach(var nodes in new[]{ManualNodes((0,0),(100,100)),ManualNodes((0,0),(30,double.NaN),(70,70),(100,100)),ManualNodes((0,0),(70,70),(30,80),(100,100)),ManualNodes((0,0),(30,20),(70,30),(100,40))})Reject(()=>ApplyManual(backend,nodes),"INVALID_CURVE");Check(MsiManualIoPorts.Rows.Count==0&&MsiManualIoPorts.TimerArms==0,"Original public validation rejects malformed or weak final nodes before any manual IO");});
        ManualCase("msi-manual-original-unadmitted-sleep-gate",backend=>{Set(backend,"suspendGateEpoch",1L);Reject(()=>ApplyManual(backend),"FAN_WRITE_SUPERSEDED");Check(MsiManualIoPorts.Rows.Count==0,"Original public manual request cannot invent admission through the sleep gate");});
        ManualCase("msi-manual-original-extra-response-byte",backend=>{MsiManualIoPorts.Tables=MsiManualIoPorts.Tables.Select(b=>b.Concat(new byte[]{249}).ToArray()).ToArray();MsiManualIoPorts.TableReadLength=32;ApplyManual(backend);Check(MsiManualIoPorts.Rows.Where(r=>r.Stage=="write"&&r.Method=="Set_Fan").All(r=>r.Data.Length==32&&r.Data[31]!=249),"Original32-byte request preserves exactly31 payload bytes and does not claim the extra response byte");});
    }
}
